//! Tests of the Validate rules of a gain schedule (specification 35, C10 Validate; annex N10): the continuity check of the active gains,
//! the variables that carry them, the start of a run at its operating point, and the parameter overrides that every run writes. The tank is
//! the one of `control-studio-gain-schedule.test.ts`, generated by the schedule's own setup.

#![allow(clippy::float_cmp)] // The operating points and the continuity fraction are exact values.

use std::collections::BTreeMap;

use serde_json::{json, Value};

use super::*;
use crate::identification::connected_record::{
    RunConditions, RunEvidence, ValidationChannel, ValidationRun, ValidationSample, ValidationValue,
};
use crate::identification::independent_validation::RequirementStatus;
use crate::loop_definition::{
    Action, LoopDefinition, LoopScope, ModeWhenTrue, RealType, SchedulingVariable,
};
use crate::recording::channels::ChannelQuality;
use crate::setup::catalog::{decode_catalog_answer, CompiledCatalog};
use crate::setup::loop_bindings::FormSignal;
use crate::setup::pid_loop::{ModeChoice, SignalChoice};
use crate::setup::schedule_loop::{
    schedule_loop_definitions, ScheduleLoopDraft, SchedulePointDraft, SchedulingVariableDraft,
};
use crate::tuning::candidate::CandidateSource;
use crate::tuning::project_candidate::ProjectCandidate;
use crate::tuning::structure::{ParallelGains, Structure};
use crate::validation::isolated_run_protocol::IsolatedParameterType;
use crate::validation::isolated_run_sampling::isolated_record_every;
use crate::validation::requirement_record::RunRequirementResult;
use crate::validation::run_validation::RecordedRunEvaluation;

fn scope() -> LoopScope {
    LoopScope {
        project_id: "project:validate".to_string(),
        runtime_id: "runtime-1".to_string(),
    }
}

#[allow(clippy::needless_pass_by_value)] // A test fixture: it takes the JSON literals its callers write in place.
fn decode(control: Value) -> CompiledCatalog {
    decode_catalog_answer(&json!({ "ok": true, "processImage": {}, "controlSymbols": control }))
        .expect("the compiled answer decodes")
        .control
}

/// The tank's program symbols: the level, the setpoint, the valve, the manual output, the mode, the startup flag and the four table gains.
fn tank() -> CompiledCatalog {
    decode(json!({
        "symbols": [
            { "symbol": "P1.LevelM", "type": "LREAL", "address": "%IL0" },
            { "symbol": "P1.SetpointM", "type": "LREAL", "address": "%ML0" },
            { "symbol": "P1.ValvePct", "type": "LREAL", "address": "%QL0" },
            { "symbol": "P1.ManualPct", "type": "LREAL", "address": "%ML8" },
            { "symbol": "P1.Auto", "type": "BOOL" },
            { "symbol": "P1.Started", "type": "BOOL" },
            { "symbol": "P1.KpLow", "type": "LREAL" },
            { "symbol": "P1.KiLow", "type": "LREAL" },
            { "symbol": "P1.KpHigh", "type": "LREAL" },
            { "symbol": "P1.KiHigh", "type": "LREAL" }
        ],
        "controllers": [
            { "instance": "P1", "type": "Main", "tasks": [{ "name": "MainTask", "intervalMs": 100 }] },
            { "instance": "P1.Loop", "type": "Control.PID", "tasks": [{ "name": "MainTask", "intervalMs": 100 }] }
        ],
        "links": [],
        "writes": ["P1.ValvePct"]
    }))
}

fn signal(symbol: &str, unit: &str, minimum: f64, maximum: f64) -> FormSignal {
    FormSignal {
        symbol: symbol.to_string(),
        unit: unit.to_string(),
        minimum: Some(minimum),
        maximum: Some(maximum),
    }
}

/// The tank's schedule: Low at 0.09 m and High at 0.49 m, each with a tolerance of 0.01 m.
fn draft() -> ScheduleLoopDraft {
    ScheduleLoopDraft {
        name: "Tank level".to_string(),
        action: Action::Direct,
        instance: "P1.Loop".to_string(),
        parameter_record: "P1.Parameters".to_string(),
        scheduling: SchedulingVariableDraft {
            symbol: "P1.LevelM".to_string(),
            unit: "m".to_string(),
        },
        process_variable: signal("P1.LevelM", "m", 0.0, 2.0),
        manipulated_variable: signal("P1.ValvePct", "%", 0.0, 100.0),
        setpoint: SignalChoice {
            symbol: "P1.SetpointM".to_string(),
            unit: None,
            minimum: None,
            maximum: None,
        },
        mode: ModeChoice {
            symbol: "P1.Auto".to_string(),
            when_true: ModeWhenTrue::Auto,
        },
        manual_output: "P1.ManualPct".to_string(),
        points: vec![
            SchedulePointDraft {
                name: "Low".to_string(),
                value: Some(0.09),
                tolerance: Some(0.01),
                proportional_gain: "P1.KpLow".to_string(),
                integral_gain: "P1.KiLow".to_string(),
            },
            SchedulePointDraft {
                name: "High".to_string(),
                value: Some(0.49),
                tolerance: Some(0.01),
                proportional_gain: "P1.KpHigh".to_string(),
                integral_gain: "P1.KiHigh".to_string(),
            },
        ],
        experiment_step: None,
        experiment_duration_seconds: None,
        startup_flag: Some("P1.Started".to_string()),
    }
}

fn tank_loops() -> Vec<LoopDefinition> {
    schedule_loop_definitions(&tank(), &scope(), &draft()).expect("the tank's schedule")
}

fn gains(proportional: f64, integral: f64) -> ParallelGains {
    ParallelGains {
        proportional_gain: proportional,
        integral_gain: integral,
        derivative_gain: 0.0,
    }
}

#[test]
fn the_continuity_limit_is_the_fraction_of_the_gains_span_over_the_points() {
    assert_eq!(CONTINUITY_FRACTION, 0.10);
    assert_eq!(continuity_limit(2.0), 0.2);
    assert_eq!(
        continuity_limit(0.0),
        0.0,
        "a gain with no span may not change"
    );
}

#[test]
fn a_gain_that_is_the_same_at_every_point_must_not_change() {
    assert!(continuity_holds(&[2.0, 2.0, 2.0], 0.0));
    assert!(
        !continuity_holds(&[2.0, 2.000_000_1], 0.0),
        "any change of a gain with no span is discontinuous"
    );
}

#[test]
fn a_gain_that_moves_within_the_limit_between_adjacent_samples_is_continuous() {
    assert!(continuity_holds(&[0.0020, 0.0021, 0.0023], 0.02));
    assert!(continuity_holds(&[], 0.02), "no samples hold trivially");
    assert!(
        continuity_holds(&[0.002], 0.02),
        "one sample holds trivially"
    );
}

#[test]
fn a_jump_above_the_limit_between_adjacent_samples_is_discontinuous() {
    assert!(
        !continuity_holds(&[0.0020, 0.0050], 0.02),
        "a step of 0.003 is above 0.002"
    );
    // The change is taken between adjacent samples, so a series that rises in small steps still fails at its large step.
    assert!(!continuity_holds(&[0.0020, 0.0021, 0.0050], 0.02));
}

#[test]
fn the_limit_itself_is_continuous_and_a_recorded_value_must_be_finite() {
    assert!(
        continuity_holds(&[0.0, 0.1], 1.0),
        "a change equal to the limit is allowed"
    );
    assert!(!continuity_holds(&[0.0, f64::NAN], 1.0));
    assert!(!continuity_holds(&[f64::INFINITY, 0.0], 1.0));
}

#[test]
fn the_active_gains_are_the_records_proportional_and_integral_gains() {
    assert_eq!(
        active_gain_symbols("P1.Parameters"),
        (
            "P1.Parameters.ProportionalGain".to_string(),
            "P1.Parameters.IntegralGain".to_string()
        )
    );
}

#[test]
fn a_run_starts_the_scheduling_variable_at_its_points_value() {
    let scheduling = SchedulingVariable {
        symbol: "P1.LevelM".to_string(),
        unit: "m".to_string(),
        iec_type: RealType::Lreal,
    };
    let loops = tank_loops();
    let schedule = loops[1]
        .controller
        .project
        .as_ref()
        .and_then(|project| project.schedule.clone())
        .expect("the High loop holds the schedule");
    let high = schedule.own_point().expect("High is the point it tunes");
    assert_eq!(
        run_start(&scheduling, high),
        ("P1.LevelM".to_string(), 0.49)
    );
}

#[test]
fn every_run_writes_the_gains_of_every_point_of_the_table() {
    let loops = tank_loops();
    let schedule = loops[0]
        .controller
        .project
        .as_ref()
        .and_then(|project| project.schedule.clone())
        .expect("the Low loop holds the schedule");
    let candidate = [gains(2.0, 0.2), gains(3.0, 0.3)];
    let overrides =
        run_overrides(&loops[0], &schedule, &candidate).expect("the schedule's run requests");
    let written: Vec<(&str, f64, &str)> = overrides
        .iter()
        .map(|item| (item.symbol.as_str(), item.value, item.unit.as_str()))
        .collect();
    assert_eq!(
        written,
        vec![
            ("P1.KpLow", 2.0, "%/m"),
            ("P1.KiLow", 0.2, "%/(m*s)"),
            ("P1.KpHigh", 3.0, "%/m"),
            ("P1.KiHigh", 0.3, "%/(m*s)"),
        ]
    );
    for item in &overrides {
        assert!(matches!(item.iec_type, IsolatedParameterType::Lreal));
        assert_eq!((item.minimum, item.maximum), (-1e6, 1e6));
    }
    assert_eq!(
        overrides[2].convention,
        "Scheduled proportional gain at High"
    );
}

#[test]
fn the_run_of_the_other_point_writes_the_same_table() {
    // Each run takes the schedule its own loop declares, which names that loop's point (`run_requests.rs`); the table is the same.
    let loops = tank_loops();
    let candidate = [gains(2.0, 0.2), gains(3.0, 0.3)];
    let from_low = run_overrides(
        &loops[0],
        schedule_of_loop(&loops[0]).expect("the Low loop holds its schedule"),
        &candidate,
    )
    .expect("the Low run");
    let from_high = run_overrides(
        &loops[1],
        schedule_of_loop(&loops[1]).expect("the High loop holds its schedule"),
        &candidate,
    )
    .expect("the High run");
    let symbols = |items: &[IsolatedParameterOverride]| -> Vec<(String, f64)> {
        items
            .iter()
            .map(|item| (item.symbol.clone(), item.value))
            .collect()
    };
    assert_eq!(symbols(&from_low), symbols(&from_high));
}

#[test]
fn a_run_needs_one_pair_of_gains_for_each_point() {
    let loops = tank_loops();
    let schedule = loops[0]
        .controller
        .project
        .as_ref()
        .and_then(|project| project.schedule.clone())
        .expect("the schedule");
    let failure = run_overrides(&loops[0], &schedule, &[gains(2.0, 0.2)])
        .expect_err("one pair is not one per point");
    assert!(failure
        .message
        .contains("one pair of gains for each operating point"));
}

/// The tank's candidate as Tune writes it: the Low point's gains, and the values of the whole table.
fn table_candidate() -> ProjectCandidate {
    ProjectCandidate {
        applied: false,
        source: CandidateSource::Manual,
        structure: Structure::PI,
        gains: gains(2.0, 0.2),
        values: BTreeMap::from([
            ("P1.KpLow".to_owned(), 2.0),
            ("P1.KiLow".to_owned(), 0.2),
            ("P1.KpHigh".to_owned(), 3.0),
            ("P1.KiHigh".to_owned(), 0.3),
        ]),
    }
}

/// A run of the tank's schedule: each sample is `(time in s, proportional gain, integral gain)`, with both gains recorded as good values.
fn recorded_run(samples: &[(f64, f64, f64)]) -> ValidationRun {
    let samples: Vec<ValidationSample> = samples
        .iter()
        .enumerate()
        .map(
            |(index, &(time, proportional, integral))| ValidationSample {
                time_seconds: time,
                sequence: u64::try_from(index).expect("a few samples"),
                values: BTreeMap::from([
                    (
                        "P1.Parameters.ProportionalGain".to_owned(),
                        ValidationValue {
                            value: Some(proportional),
                            quality: ChannelQuality::Good,
                        },
                    ),
                    (
                        "P1.Parameters.IntegralGain".to_owned(),
                        ValidationValue {
                            value: Some(integral),
                            quality: ChannelQuality::Good,
                        },
                    ),
                ]),
            },
        )
        .collect();
    ValidationRun {
        id: "schedule-run".to_owned(),
        evidence: RunEvidence::StExecuted,
        parameters: BTreeMap::new(),
        conditions: RunConditions {
            initial_state: BTreeMap::new(),
            events: Vec::new(),
            duration_seconds: 2.0,
            sample_times_seconds: samples.iter().map(|sample| sample.time_seconds).collect(),
            seed: 1,
            model_revision: "model".to_owned(),
            program_revision: "program".to_owned(),
            parameter_schema_revision: "schema".to_owned(),
        },
        channels: vec![
            ValidationChannel {
                id: "P1.Parameters.ProportionalGain".to_owned(),
                unit: "%/m".to_owned(),
            },
            ValidationChannel {
                id: "P1.Parameters.IntegralGain".to_owned(),
                unit: "%/(m*s)".to_owned(),
            },
        ],
        samples,
    }
}

#[test]
fn a_constant_gain_with_no_span_passes_the_verdict() {
    let samples = [(0.0, 2.0), (1.0, 2.0), (2.0, 2.0)];
    let verdict = continuity_verdict(&[ActiveGain {
        name: "proportional gain",
        unit: "%/m",
        span: 0.0,
        samples: Some(&samples[..]),
    }]);
    assert_eq!(verdict.status, RequirementStatus::Pass);
    assert_eq!(verdict.value, None);
}

#[test]
fn a_step_above_the_limit_fails_the_verdict_and_names_the_gain() {
    let samples = [(0.0, 0.0020), (1.0, 0.0050)];
    let verdict = continuity_verdict(&[ActiveGain {
        name: "integral gain",
        unit: "%/(m*s)",
        span: 0.02,
        samples: Some(&samples[..]),
    }]);
    assert_eq!(verdict.status, RequirementStatus::Fail);
    assert!(
        verdict.reason.contains("integral gain"),
        "{}",
        verdict.reason
    );
    assert_eq!(verdict.unit, "%/(m*s)");
    assert!(verdict
        .value
        .is_some_and(|change| (change - 0.003).abs() < 1e-9));
    assert!(verdict
        .limit
        .is_some_and(|limit| (limit - 0.002).abs() < 1e-9));
}

#[test]
fn a_missing_series_is_inconclusive() {
    let proportional = [(0.0, 2.0), (1.0, 2.05)];
    let verdict = continuity_verdict(&[
        ActiveGain {
            name: "proportional gain",
            unit: "%/m",
            span: 1.0,
            samples: Some(&proportional[..]),
        },
        ActiveGain {
            name: "integral gain",
            unit: "%/(m*s)",
            span: 0.1,
            samples: None,
        },
    ]);
    assert_eq!(verdict.status, RequirementStatus::Inconclusive);
    assert!(
        verdict.reason.contains("integral gain"),
        "{}",
        verdict.reason
    );
}

#[test]
fn a_break_outranks_a_missing_series() {
    let integral = [(0.0, 0.2), (1.0, 0.25)];
    let verdict = continuity_verdict(&[
        ActiveGain {
            name: "proportional gain",
            unit: "%/m",
            span: 1.0,
            samples: None,
        },
        ActiveGain {
            name: "integral gain",
            unit: "%/(m*s)",
            span: 0.1,
            samples: Some(&integral[..]),
        },
    ]);
    assert_eq!(verdict.status, RequirementStatus::Fail);
    assert!(
        verdict.reason.contains("integral gain"),
        "{}",
        verdict.reason
    );
}

#[test]
fn a_gain_that_is_not_a_finite_number_fails_the_verdict() {
    let proportional = [(0.0, 2.0), (1.0, f64::NAN)];
    let verdict = continuity_verdict(&[ActiveGain {
        name: "proportional gain",
        unit: "%/m",
        span: 1.0,
        samples: Some(&proportional[..]),
    }]);
    assert_eq!(verdict.status, RequirementStatus::Fail);
    assert!(
        verdict.reason.contains("not a finite number"),
        "{}",
        verdict.reason
    );
    assert_eq!(verdict.value, None);
}

#[test]
fn a_candidate_run_whose_integral_gain_breaks_fails_the_evaluation_and_names_the_gain() {
    let loops = tank_loops();
    let rule = continuity_rule(&loops[0], Some(&table_candidate()), 1)
        .expect("the tank's table holds its gains")
        .expect("a schedule has a continuity rule");
    // The proportional gain moves by 0.05 against its limit of 0.1; the integral gain moves by 0.02 against its limit of 0.01.
    let run = recorded_run(&[(0.0, 2.0, 0.2), (1.0, 2.05, 0.2), (2.0, 2.1, 0.22)]);
    let mut evaluation = RecordedRunEvaluation {
        status: RequirementStatus::Pass,
        run: run.clone(),
        specification: Vec::new(),
        requirements: Vec::new(),
        scope: String::new(),
    };
    add_continuity_result(&rule, &run, &mut evaluation);
    assert_eq!(evaluation.status, RequirementStatus::Fail);
    assert_eq!(evaluation.requirements.len(), 1);
    let row = &evaluation.requirements[0];
    assert_eq!(row.id, "active-gains-change-continuously");
    assert_eq!(row.kind, "gain-continuity");
    assert_eq!(row.status, RequirementStatus::Fail);
    assert_eq!(row.unit, "%/(m*s)");
    assert!(row.reason.contains("integral gain"), "{}", row.reason);
    assert!(!row.reason.contains("proportional gain"), "{}", row.reason);
}

#[test]
fn a_candidate_run_whose_gains_hold_keeps_the_evaluation_passing() {
    let loops = tank_loops();
    let rule = continuity_rule(&loops[0], Some(&table_candidate()), 1)
        .expect("the tank's table holds its gains")
        .expect("a schedule has a continuity rule");
    let run = recorded_run(&[(0.0, 2.0, 0.2), (1.0, 2.05, 0.205), (2.0, 2.1, 0.21)]);
    let mut evaluation = RecordedRunEvaluation {
        status: RequirementStatus::Pass,
        run: run.clone(),
        specification: Vec::new(),
        requirements: Vec::new(),
        scope: String::new(),
    };
    add_continuity_result(&rule, &run, &mut evaluation);
    assert_eq!(evaluation.status, RequirementStatus::Pass);
    assert_eq!(evaluation.requirements.len(), 1);
    assert_eq!(evaluation.requirements[0].status, RequirementStatus::Pass);
}

