/// The continuity row that a candidate run's evaluation gets from the rule (C10 Validate).
fn continuity_row(rule: &ContinuityRule, run: &ValidationRun) -> RunRequirementResult {
    let mut evaluation = RecordedRunEvaluation {
        status: RequirementStatus::Pass,
        run: run.clone(),
        specification: Vec::new(),
        requirements: Vec::new(),
        scope: String::new(),
    };
    add_continuity_result(rule, run, &mut evaluation);
    evaluation
        .requirements
        .into_iter()
        .next()
        .expect("the continuity row")
}

#[test]
fn an_averaged_candidate_run_is_inconclusive_with_the_sentence_that_says_so() {
    let loops = tank_loops();
    let rule = continuity_rule(&loops[0], Some(&table_candidate()), 4)
        .expect("the tank's table holds its gains")
        .expect("a schedule has a continuity rule");
    // Both gains hold their limits in this run, so only the averaging makes the row Inconclusive.
    let run = recorded_run(&[(0.0, 2.0, 0.2), (1.0, 2.05, 0.205), (2.0, 2.1, 0.21)]);
    let row = continuity_row(&rule, &run);
    assert_eq!(row.id, "active-gains-change-continuously");
    assert_eq!(row.kind, "gain-continuity");
    assert_eq!(row.status, RequirementStatus::Inconclusive);
    assert_eq!(row.value, None);
    assert_eq!(row.limit, None);
    assert_eq!(row.unit, "");
    assert_eq!(
        row.reason,
        "The run averages its samples, so the continuity of the active gains cannot be judged from the recording."
    );
}

#[test]
fn an_unaveraged_candidate_run_keeps_its_verdict() {
    let loops = tank_loops();
    let rule = continuity_rule(&loops[0], Some(&table_candidate()), 1)
        .expect("the tank's table holds its gains")
        .expect("a schedule has a continuity rule");
    let holding = recorded_run(&[(0.0, 2.0, 0.2), (1.0, 2.05, 0.205), (2.0, 2.1, 0.21)]);
    let breaking = recorded_run(&[(0.0, 2.0, 0.2), (1.0, 2.05, 0.2), (2.0, 2.1, 0.22)]);
    assert_eq!(
        continuity_row(&rule, &holding).status,
        RequirementStatus::Pass
    );
    assert_eq!(
        continuity_row(&rule, &breaking).status,
        RequirementStatus::Fail
    );
}

#[test]
fn a_schedule_candidate_run_of_40_seconds_at_100_ms_records_every_sample_and_is_judged() {
    let loops = tank_loops();
    // 401 grid points fit the isolated limits at a record period of 1 (A7), so the run's continuity is judged on every scan.
    assert!(records_every_sample(&loops[0], 100, 40_000, 6));
    let rule = continuity_rule(&loops[0], Some(&table_candidate()), 1)
        .expect("the tank's table holds its gains")
        .expect("a schedule has a continuity rule");
    let run = recorded_run(&[(0.0, 2.0, 0.2), (1.0, 2.05, 0.205), (2.0, 2.1, 0.21)]);
    assert_eq!(continuity_row(&rule, &run).status, RequirementStatus::Pass);
}

#[test]
fn a_schedule_candidate_run_of_24_hours_at_100_ms_still_averages_and_is_inconclusive() {
    let loops = tank_loops();
    // 864,001 grid points exceed the 100,000 samples a run may hold (A7), so the period stays above 1 and the run averages.
    assert!(!records_every_sample(&loops[0], 100, 86_400_000, 6));
    let period = isolated_record_every(100, 86_400_000, 6);
    assert!(period > 1);
    let rule = continuity_rule(&loops[0], Some(&table_candidate()), period)
        .expect("the tank's table holds its gains")
        .expect("a schedule has a continuity rule");
    let run = recorded_run(&[(0.0, 2.0, 0.2), (1.0, 2.05, 0.205), (2.0, 2.1, 0.21)]);
    let row = continuity_row(&rule, &run);
    assert_eq!(row.status, RequirementStatus::Inconclusive);
    assert_eq!(
        row.reason,
        "The run averages its samples, so the continuity of the active gains cannot be judged from the recording."
    );
}

#[test]
fn a_schedule_run_whose_cells_do_not_fit_keeps_its_period() {
    let loops = tank_loops();
    // 401 grid points of 5,000 channels are 2,005,000 cells, more than the 1,600,000 a run may hold (A7).
    assert!(!records_every_sample(&loops[0], 100, 40_000, 5_000));
}

#[test]
fn a_loop_without_a_schedule_keeps_its_period() {
    let lesson = LoopDefinition::decode(include_str!(
        "../../../../editors/vscode/media/examples/control/14-integrated-capstones/84-independent/control-loop.json"
    ))
    .expect("lesson 84 decodes");
    // Lesson 84 fits the isolated limits at 40 s and 100 ms too, but only a schedule's run records every sample (C10).
    assert!(!records_every_sample(&lesson, 100, 40_000, 6));
}
